// Real data: TPC-H SF-10 lineitem generated by DuckDB (scripts/tpch_prep.py), stored sorted by
// l_shipdate so the date column run-length-encodes the way a clustered fact table does.
//   Q1-shaped:  SELECT l_returnflag, l_linestatus, COUNT(*), SUM(price), MIN(price), MAX(price), SUM(price*0.01)
//               WHERE l_shipdate <= DATE '1998-09-02' GROUP BY 1, 2          (composite dictionary key)
//   Q6-shaped:  same aggregates, no GROUP BY, WHERE l_shipdate in [1994-01-01, 1995-01-01)
// (price = l_extendedprice in cents.  Q6's discount/quantity predicates are not expressible with a
//  single RLE predicate column and are dropped; README states the deviation.)
// Both are checked against the CPU reference AND against DuckDB's answer for the same SQL.
#include <fstream>
#include <thread>
#include "../src/cpu/cpu.hpp"
#include "../src/kernels/variants.hpp"
#include "util.hpp"

double quick_read_bw();

namespace {
template <class T>
std::vector<T> load(const std::string& path) {
  std::ifstream f(path, std::ios::binary | std::ios::ate);
  if (!f) { fprintf(stderr, "missing %s\n", path.c_str()); exit(1); }
  size_t n = f.tellg() / sizeof(T);
  std::vector<T> v(n);
  f.seekg(0);
  f.read((char*)v.data(), n * sizeof(T));
  return v;
}
struct Expected { u64 key; u64 cnt; i64 sum; i32 mn, mx; };
std::vector<Expected> load_expected(const std::string& path) {
  std::vector<Expected> out;
  std::ifstream f(path);
  std::string line;
  while (std::getline(f, line)) {
    Expected e{};
    char rf, ls;
    long long c, s, mn, mx;
    if (sscanf(line.c_str(), "%c,%c,%lld,%lld,%lld,%lld", &rf, &ls, &c, &s, &mn, &mx) != 6) continue;
    e.key = rf == '-' ? 0x5eedull : ((u64)(u8)rf << 32) | (u8)ls;
    e.cnt = c; e.sum = s; e.mn = (i32)mn; e.mx = (i32)mx;
    out.push_back(e);
  }
  std::sort(out.begin(), out.end(), [](auto& a, auto& b) { return a.key < b.key; });
  return out;
}
}  // namespace

int run_tpch(const Args& a) {
  std::string dir = a.get("dir", "/kaggle/tmp/tpch");
  int iters = (int)a.num("iters", 30), warm = (int)a.num("warmup", 5);
  int threads = (int)std::thread::hardware_concurrency();
  auto rf = load<u8>(dir + "/returnflag.u8");
  auto ls = load<u8>(dir + "/linestatus.u8");
  auto sd = load<u16>(dir + "/shipdate.u16");
  auto price = load<i32>(dir + "/extprice.i32");
  auto params = load<i32>(dir + "/params.i32");  // q1_hi, q6_lo, q6_hi (days since 1992-01-01)
  const u64 n = price.size();
  printf("tpch lineitem rows=%llu\n", (unsigned long long)n);
  // shared columns: RLE of the (sorted) ship date, values = price in cents
  HostData base;
  base.n = n;
  base.vals = price;
  for (u64 i = 0; i < n; ++i)
    if (i + 1 == n || sd[i + 1] != sd[i]) { base.run_end.push_back((u32)(i + 1)); base.run_val.push_back(sd[i]); }
  printf("shipdate RLE: %zu runs (%.0f rows/run)\n", base.run_end.size(), (double)n / base.run_end.size());
  auto vars = std::vector<Variant>{};
  for (auto& v : all_variants()) if (!v.ablation) vars.push_back(v);
  double bw = quick_read_bw();
  cudaStream_t st; CK(cudaStreamCreate(&st));
  int fails = 0;
  for (int q = 0; q < 2; ++q) {
    HostData H = base;
    u16 lo, hi;
    std::string qname;
    if (q == 0) {  // composite dictionary key (returnflag, linestatus)
      qname = "Q1";
      H.kind = KeyKind::COMP; H.card1 = 4; H.card2 = 2; H.log_card2 = 1; H.card = 8;
      H.dict1 = {'A', 'N', 'R', 'X'}; H.dict2 = {'F', 'O'};
      H.codes.resize(n * 2); H.codes2.resize(n * 2);
      for (u64 i = 0; i < n; ++i) {
        reinterpret_cast<u16*>(H.codes.data())[i] = rf[i];
        reinterpret_cast<u16*>(H.codes2.data())[i] = ls[i];
      }
      lo = 0; hi = (u16)(params[0] + 1);
    } else {  // global aggregate: constant one-entry dictionary
      qname = "Q6";
      H.kind = KeyKind::U8; H.card = 1; H.dict = {0x5eedull};
      H.codes.assign(n, 0);
      lo = (u16)params[1]; hi = (u16)params[2];
    }
    H.spec.rows = n;
    double t0 = now_ms();
    auto ref = cpu_reference(H, lo, hi);
    double ref_ms = now_ms() - t0;
    auto exp = load_expected(dir + (q == 0 ? "/q1_expected.csv" : "/q6_expected.csv"));
    bool duck_ok = exp.size() == ref.size();
    for (size_t i = 0; duck_ok && i < ref.size(); ++i)
      duck_ok = exp[i].key == ref[i].key && exp[i].cnt == ref[i].a.cnt && exp[i].sum == ref[i].a.sum &&
                exp[i].mn == ref[i].a.mn && exp[i].mx == ref[i].a.mx;
    printf("%s: %zu groups, reference matches DuckDB: %s\n", qname.c_str(), ref.size(), duck_ok ? "yes" : "NO");
    if (!duck_ok) ++fails;
    std::vector<double> cms;
    for (int i = 0; i < 11; ++i) { double t = now_ms(); cpu_engine(H, lo, hi, threads); if (i) cms.push_back(now_ms() - t); }
    Stat cpu = stats(cms);
    DevData D; D.upload(H);
    GTable T; T.alloc(table_capacity(H.card));
    Results R; R.alloc(T.cap);
    DevRef dref; dref.upload(ref);
    for (auto& v : vars) {
      RunCtx c; c.D = &D; c.lo = lo; c.hi = hi; c.T = &T; c.R = &R; c.st = st; c.sel_est = rle_count_selected(H, lo, hi);
      Json j;
      j.s("exp", "tpch").s("query", qname).s("variant", v.name).n("rows", (double)n).n("bytes_in", (double)H.bytes_compressed())
          .n("cpu_ms", cpu.med).n("cpu_threads", threads).n("ref_ms", ref_ms).b("reference_matches_duckdb", duck_ok)
          .n("selected", (double)c.sel_est).n("achievable_read_gbs", bw);
      try {
        v.run(c);
        CheckResult r = check_results(R, dref, st);
        j.b("correct", r.ok).n("groups", (double)r.groups).n("max_rel_err_dsum", r.max_rel_dsum);
        if (!r.ok) { ++fails; printf("  %-16s INCORRECT %s\n", v.name.c_str(), r.msg.c_str()); }
        else {
          Clk c0 = clocks();
          Stat s = time_gpu([&] { v.run(c); }, st, warm, iters);
          Clk c1 = clocks();
          double gbs = H.bytes_compressed() / (s.med * 1e6);
          j.n("median_ms", s.med).n("p25_ms", s.p25).n("p75_ms", s.p75).n("iqr_ms", s.p75 - s.p25).n("n_iter", s.n)
              .n("eff_gbs", gbs).n("bw_pct", 100 * gbs / bw).n("speedup_vs_cpu", cpu.med / s.med);
          put_clocks(j, c0, c1);
          printf("  %s %-16s %8.3f ms  %5.1f%% bw  %6.1fx cpu(%.1f ms)\n", qname.c_str(), v.name.c_str(), s.med, 100 * gbs / bw,
                 cpu.med / s.med, cpu.med);
        }
      } catch (const Skip& s) { j.b("correct", false).s("skipped", s.what()); }
      emit(j);
    }
    dref.release(); R.release(); T.release(); D.release();
    release_v4_scratch(); release_sort_scratch();
  }
  return fails ? 1 : 0;
}

// Write one synthetic sweep point decoded (key u64, val i32, pred u16) for the cuDF reference,
// plus the reference answer's checksums per selectivity.
int run_dump(const Args& a) {
  GenSpec g; g.rows = (u64)a.num("rows", 10e6); g.card = (u32)a.num("card", 256); g.zipf = a.num("skew", 0); g.seed = 42;
  std::string out = a.get("out", "/kaggle/tmp/dump");
  HostData H; gen_setup(H, g); gen_rows_host(H, build_zipf_alias(g.card, g.zipf));
  std::vector<u64> keys(H.n); std::vector<u16> pred(H.n);
  size_t run = 0;
  for (u64 r = 0; r < H.n; ++r) { while (H.run_end[run] <= r) ++run; pred[r] = H.run_val[run]; keys[r] = H.decode(H.code(r)); }
  std::ofstream(out + "_key.u64", std::ios::binary).write((const char*)keys.data(), H.n * 8);
  std::ofstream(out + "_val.i32", std::ios::binary).write((const char*)H.vals.data(), H.n * 4);
  std::ofstream(out + "_pred.u16", std::ios::binary).write((const char*)pred.data(), H.n * 2);
  std::ofstream ex(out + "_expected.txt");
  for (double s : a.list("sels", "1,10,50,100")) {
    auto ref = cpu_reference(H, 0, (u16)s);
    u64 cnt = 0; i64 sum = 0;
    for (auto& r : ref) { cnt += r.a.cnt; sum += r.a.sum; }
    ex << (int)s << " " << ref.size() << " " << cnt << " " << sum << "\n";
  }
  return 0;
}
